def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # find monochrome rectangular frames; recognize complete perimeter bounding boxes
    boxes=[]
    for c in range(1,10):
      pts=[(r,x) for r in range(h) for x in range(w) if g[r][x]==c]
      if not pts: continue
      r0=min(r for r,x in pts); r1=max(r for r,x in pts); x0=min(x for r,x in pts); x1=max(x for r,x in pts)
      if r1-r0>=2 and x1-x0>=2 and all(g[r0][x]==c and g[r1][x]==c for x in range(x0,x1+1)) and all(g[r][x0]==c and g[r][x1]==c for r in range(r0,r1+1)):
        boxes.append((c,r0,r1,x0,x1))
    src=None
    for b in boxes:
      c,a,z,x,y=b
      if any(g[r][q]==c for r in range(a+1,z) for q in range(x+1,y)):
        src=b; break
    if not src:return out
    c,a,z,x,y=src; patt=[[g[r][q]!=0 for q in range(x+1,y)] for r in range(a+1,z)]
    # copy into same-sized interior recipients; remove unmatched empty frames
    for d,u,v,p,q in boxes:
      if (d,u,v,p,q)==src: continue
      for r in range(u,v+1):
        for s in range(p,q+1): out[r][s]=0
      if v-u-1==len(patt) and q-p-1==len(patt[0]):
        for i,row in enumerate(patt):
          for j,val in enumerate(row): out[u+1+i][p+1+j]=d if val else 0
    return out
