def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]; boxes=[]
    for c in range(1,10):
        pts=[(r,x) for r in range(h) for x in range(w) if g[r][x]==c]
        if not pts: continue
        a=min(r for r,x in pts); z=max(r for r,x in pts); p=min(x for r,x in pts); q=max(x for r,x in pts)
        if z-a>=2 and q-p>=2 and all(g[a][x]==c and g[z][x]==c for x in range(p,q+1)) and all(g[r][p]==c and g[r][q]==c for r in range(a,z+1)):
            boxes.append((c,a,z,p,q))
    src=next((b for b in boxes if any(g[r][x]==b[0] for r in range(b[1]+1,b[2]) for x in range(b[3]+1,b[4]))),None)
    if src is None: return out
    c,a,z,p,q=src; pattern=[[g[r][x]==c for x in range(p+1,q)] for r in range(a+1,z)]
    H=len(pattern); W=len(pattern[0])
    for d,u,v,s,t in boxes:
        if (d,u,v,s,t)==src: continue
        if v-u-1==H and t-s-1==W:
            for i in range(H):
                for j in range(W): out[u+1+i][s+1+j]=d if pattern[i][j] else 0
    return out
